import { motion, useScroll, useTransform } from 'framer-motion';
import React, { useRef } from 'react';
import clsx from 'clsx';
import './AcidScrollStack.css';

export interface AcidScrollStackProps {
    children: React.ReactNode[];
    className?: string;
}

export const AcidScrollStack = ({
    children,
    className
}: AcidScrollStackProps) => {
    return (
        <div className={clsx('ac-scroll-stack', className)}>
            {children.map((child, index) => (
                <StackItem key={index} index={index}>
                    {child}
                </StackItem>
            ))}
        </div>
    );
};

const StackItem = ({ children, index }: { children: React.ReactNode, index: number }) => {
    const ref = useRef<HTMLDivElement>(null);
    const { scrollYProgress } = useScroll({
        target: ref,
        offset: ["start end", "start start"]
    });

    const scale = useTransform(scrollYProgress, [0, 1], [0.95, 1]);
    const opacity = useTransform(scrollYProgress, [0, 0.5], [0, 1]);

    return (
        <motion.div
            ref={ref}
            style={{
                scale,
                opacity,
                position: 'sticky',
                top: `${40 + index * 20}px`,
                zIndex: index
            }}
            className="ac-stack-item-wrapper"
        >
            <div className="ac-stack-card">
                <div className="ac-stack-tag">SEC_0{index + 1}</div>
                {children}
            </div>
        </motion.div>
    );
};

.ac-scroll-stack {
    display: flex;
    flex-direction: column;
    gap: 40px;
    padding-bottom: 200px;
}

.ac-stack-item-wrapper {
    width: 100%;
    transform-origin: top;
    will-change: transform, opacity;
}

.ac-stack-card {
    background: var(--ac-surface);
    border: 1px solid var(--ac-border-muted);
    border-radius: 12px;
    padding: 2rem;
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.5);
    position: relative;
    overflow: hidden;
}

.ac-stack-card::after {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: linear-gradient(135deg, rgba(255, 255, 255, 0.02) 0%, transparent 100%);
    pointer-events: none;
}

.ac-stack-tag {
    position: absolute;
    top: 1rem;
    right: 1rem;
    font-size: 0.6rem;
    font-family: var(--font-mono);
    color: var(--ac-brand);
    border: 1px solid var(--ac-brand);
    padding: 2px 6px;
    border-radius: 4px;
    text-transform: uppercase;
}
